        nx = NX.to(tl.int64)
        ny = NY.to(tl.int64)
        nz = NZ.to(tl.int64)
        n = nx * ny * nz
        mask = idx < n
        z = idx % nz
        y = (idx // nz) % ny
        x = idx // (ny * nz)
        me_solid = tl.load(solid + idx, mask=mask, other=1) != 0
        h0 = _pull(hin, solid, 0, 0, 0, 0, 0, x, y, z, nx, ny, nz, n, idx, mask)
        h1 = _pull(hin, solid, 1, 2, 1, 0, 0, x, y, z, nx, ny, nz, n, idx, mask)
        h2 = _pull(hin, solid, 2, 1, -1, 0, 0, x, y, z, nx, ny, nz, n, idx, mask)
        h3 = _pull(hin, solid, 3, 4, 0, 1, 0, x, y, z, nx, ny, nz, n, idx, mask)
        h4 = _pull(hin, solid, 4, 3, 0, -1, 0, x, y, z, nx, ny, nz, n, idx, mask)
        h5 = _pull(hin, solid, 5, 6, 0, 0, 1, x, y, z, nx, ny, nz, n, idx, mask)
        h6 = _pull(hin, solid, 6, 5, 0, 0, -1, x, y, z, nx, ny, nz, n, idx, mask)
        h7 = _pull(hin, solid, 7, 8, 1, 1, 0, x, y, z, nx, ny, nz, n, idx, mask)
        h8 = _pull(hin, solid, 8, 7, -1, -1, 0, x, y, z, nx, ny, nz, n, idx, mask)
        h9 = _pull(hin, solid, 9, 10, 1, -1, 0, x, y, z, nx, ny, nz, n, idx, mask)
        h10 = _pull(hin, solid, 10, 9, -1, 1, 0, x, y, z, nx, ny, nz, n, idx, mask)
        h11 = _pull(hin, solid, 11, 12, 1, 0, 1, x, y, z, nx, ny, nz, n, idx, mask)
        h12 = _pull(hin, solid, 12, 11, -1, 0, -1, x, y, z, nx, ny, nz, n, idx, mask)
        h13 = _pull(hin, solid, 13, 14, 1, 0, -1, x, y, z, nx, ny, nz, n, idx, mask)
        h14 = _pull(hin, solid, 14, 13, -1, 0, 1, x, y, z, nx, ny, nz, n, idx, mask)
        h15 = _pull(hin, solid, 15, 16, 0, 1, 1, x, y, z, nx, ny, nz, n, idx, mask)
        h16 = _pull(hin, solid, 16, 15, 0, -1, -1, x, y, z, nx, ny, nz, n, idx, mask)
        h17 = _pull(hin, solid, 17, 18, 0, 1, -1, x, y, z, nx, ny, nz, n, idx, mask)
        h18 = _pull(hin, solid, 18, 17, 0, -1, 1, x, y, z, nx, ny, nz, n, idx, mask)
        drho = h0 + h1 + h2 + h3 + h4 + h5 + h6 + h7 + h8 + h9 + h10 + h11 + h12 + h13 + h14 + h15 + h16 + h17 + h18
        jx = h1 - h2 + h7 - h8 + h9 - h10 + h11 - h12 + h13 - h14
        jy = h3 - h4 + h7 - h8 - h9 + h10 + h15 - h16 + h17 - h18
        jz = h5 - h6 + h11 - h12 - h13 + h14 + h15 - h16 - h17 + h18
        rho = 1.0 + drho
        fx = rho * gx
        fy = rho * gy
        fz = rho * gz
        ux = (jx + 0.5 * fx) / rho
        uy = (jy + 0.5 * fy) / rho
        uz = (jz + 0.5 * fz) / rho
