        em = 0.05555555555555555 * (rho * 3.0 * cu)
        sp = 0.05555555555555555 * (9.0 * cu * cf - 3.0 * uf)
        sm = 0.05555555555555555 * (3.0 * cf)
        hp = 0.5 * (h1 + h2)
        hm = 0.5 * (h1 - h2)
        _put(hout, 1, h1 - wp * (hp - ep) - wm * (hm - em) + kp * sp + km * sm, idx, n, mask, me_solid)
        _put(hout, 2, h2 - wp * (hp - ep) + wm * (hm - em) + kp * sp - km * sm, idx, n, mask, me_solid)
