        cf = fy
        ep = 0.05555555555555555 * (drho + rho * (4.5 * cu * cu - 1.5 * usq))
        em = 0.05555555555555555 * (rho * 3.0 * cu)
        sp = 0.05555555555555555 * (9.0 * cu * cf - 3.0 * uf)
        sm = 0.05555555555555555 * (3.0 * cf)
        hp = 0.5 * (h3 + h4)
        hm = 0.5 * (h3 - h4)
        _put(hout, 3, h3 - wp * (hp - ep) - wm * (hm - em) + kp * sp + km * sm, idx, n, mask, me_solid)
        _put(hout, 4, h4 - wp * (hp - ep) + wm * (hm - em) + kp * sp - km * sm, idx, n, mask, me_solid)
        cu = uz
        cf = fz
        ep = 0.05555555555555555 * (drho + rho * (4.5 * cu * cu - 1.5 * usq))
        em = 0.05555555555555555 * (rho * 3.0 * cu)
        sp = 0.05555555555555555 * (9.0 * cu * cf - 3.0 * uf)
        sm = 0.05555555555555555 * (3.0 * cf)
        hp = 0.5 * (h5 + h6)
        hm = 0.5 * (h5 - h6)
        _put(hout, 5, h5 - wp * (hp - ep) - wm * (hm - em) + kp * sp + km * sm, idx, n, mask, me_solid)
        _put(hout, 6, h6 - wp * (hp - ep) + wm * (hm - em) + kp * sp - km * sm, idx, n, mask, me_solid)
        cu = ux + uy
        cf = fx + fy
        ep = 0.027777777777777776 * (drho + rho * (4.5 * cu * cu - 1.5 * usq))
        em = 0.027777777777777776 * (rho * 3.0 * cu)
        sp = 0.027777777777777776 * (9.0 * cu * cf - 3.0 * uf)
        sm = 0.027777777777777776 * (3.0 * cf)
        hp = 0.5 * (h7 + h8)
